WITH with_gaps AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) + INTERVAL '7' DAY THEN 1 ELSE 0 END AS session_start_flag FROM payments), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT s.id, s.order_id, s.amount, s.session_start_flag, s.session_no, (SELECT MAX(x.amount) FROM payments x WHERE x.order_id = s.order_id) AS max_payment_amount FROM islands s ORDER BY amount;
